code.cpp:
class Solution {
public:
    vector<string> ambiguousCoordinates(string s) {
        vector<string> result;
        int n = s.size();
        int len = n - 2; // digits are s[1..n-2]

        for (int split = 1; split < len; split++) {
            int xstart = 1, xlen = split;
            int ystart = split + 1, ylen = len - split;

            for (int xi = 0; xi < xlen; xi++) {
                // xi == 0: no decimal; xi >= 1: decimal after xi digits
                bool xvalid;
                if (xi == 0) {
                    xvalid = (s[xstart] != '0' || xlen == 1);
                } else {
                    // integer part valid if no leading zero (or single "0")
                    // fractional part valid if last digit is not '0'
                    xvalid = ((s[xstart] != '0' || xi == 1) &&
                              s[xstart + xlen - 1] != '0');
                }
                if (!xvalid) continue;

                for (int yi = 0; yi < ylen; yi++) {
                    bool yvalid;
                    if (yi == 0) {
                        yvalid = (s[ystart] != '0' || ylen == 1);
                    } else {
                        yvalid = ((s[ystart] != '0' || yi == 1) &&
                                  s[ystart + ylen - 1] != '0');
                    }
                    if (!yvalid) continue;

                    string res = "(";
                    if (xi == 0) {
                        res += s.substr(xstart, xlen);
                    } else {
                        res += s.substr(xstart, xi);
                        res += '.';
                        res += s.substr(xstart + xi, xlen - xi);
                    }
                    res += ", ";
                    if (yi == 0) {
                        res += s.substr(ystart, ylen);
                    } else {
                        res += s.substr(ystart, yi);
                        res += '.';
                        res += s.substr(ystart + yi, ylen - yi);
                    }
                    res += ')';
                    result.push_back(move(res));
                }
            }
        }

        return result;
    }
};
